declare(strict_types=1);require __DIR__.'/config.php';if($_SERVER['REQUEST_METHOD']!=='POST')mnc_page('Method not allowed','Use the contact form.');if(!empty($_POST['website']??''))mnc_page('Message received','Thank you.');$name=trim((string)($_POST['name']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$reason=trim((string)($_POST['reason']??''));$message=trim((string)($_POST['message']??''));if(!$email||$name===''||$message==='')mnc_page('Check the form','Complete the required fields.');$pdo=mnc_db();$st=$pdo->prepare('INSERT INTO contacts(name,email,reason,message,created_at) VALUES(?,?,?,?,?)');$st->execute([substr($name,0,80),$email,substr($reason,0,80),substr($message,0,3000),date(DATE_ATOM)]);mnc_page('Message received','Thank you. Your message has been recorded.');
